message.content:
{
  "description": "The creature is a single chimeric animal standing in right-facing profile on a small patch of bare ground with sparse tufts of grass. Its body is that of a large, muscular lion, covered in short tawny-brown fur with a lighter cream belly and inner legs, supported by four sturdy legs and ending in a long tail. Its head, neck, chest and wings are those of an eagle, covered in layered brown, golden-brown, cream and dark brown feathers, with a hooked beak and a sharp eye. Two large feathered wings are spread upward and outward from its upper back. The overall coloration is warm browns and golds with darker flight feathers and a dark tail tuft.",
  "parts": [
    {
      "part": "head",
      "looks_like": "eagle-like head at the front of the body facing right, with a large hooked beak that is dark gray at the tip and yellow at the base and cere, a forward-facing amber eye with a dark pupil and yellow orbital ring, and dense golden-brown feathers on the crown and cheeks with lighter cream patches on the side of the neck",
      "where": "at the anterior end of the body, attached to the feathered neck above the chest"
    },
    {
      "part": "mane",
      "looks_like": "a thick ruff of elongated shaggy feathers and fur around the lower neck and chest, dark brown mixed with cream and golden streaks, hanging down between the forelegs",
      "where": "encircling the front of the neck and covering the upper chest and throat"
    },
    {
      "part": "legs",
      "looks_like": "four thick, muscular lion-like legs covered in short tawny fur that is lighter on the undersides and inner surfaces, with visible joints and musculature",
      "where": "two forelegs under the chest and two hind legs under the hindquarters, supporting the body on the ground"
    },
    {
      "part": "feet",
      "looks_like": "four large paw-like feet with rounded toes, short dark claws, and padded soles, covered in tawny fur with lighter fur on top",
      "where": "at the distal ends of each leg, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "a long slender lion-like tail covered in short tawny fur, tapering to a dark brown to black bushy tuft at the tip",
      "where": "extending from the rear of the hindquarters, hanging down and curving slightly outward behind the hind legs"
    },
    {
      "part": "wings",
      "looks_like": "two very large outstretched wings with layered feathers, golden-brown and medium brown coverts on the upper surfaces and darker brown to gray-brown flight feathers along the trailing edges and tips, with detailed individual feather barbs visible",
      "where": "attached to the upper back behind the shoulders, spread upward and outward to the left and right above the body"
    },
    {
      "part": "feathers",
      "looks_like": "dense overlapping feathers of varying size and color - small golden-brown feathers on the head, larger layered brown and cream feathers on the neck and chest, and long broad flight feathers on the wings in shades of gold, brown, tan and dark brown",
      "where": "covering the head, neck, chest, and entire dorsal surfaces of both wings"
    },
    {
      "part": "markings",
      "looks_like": "tawny lion body with a paler cream belly and inner legs, darker brown shading along the back and hindquarters, cream-white patches on the side of the neck and chest interspersed with dark brown feathered areas, and darker brown tips on the wing feathers and tail tuft",
      "where": "over the whole body, with lighter ventral areas and darker dorsal and feathered areas"
    }
  ],
  "attached_objects": [],
  "animals": [
    "eagle",
    "lion"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 2,
  "extra_limb_pieces": 0
}
